const input = require("fs").readFileSync(0, "utf8");

function nextPermutation(nums) {
  // The pivot is the rightmost number smaller than the number after it.
  let i = nums.length - 2;
  while (i >= 0 && nums[i] >= nums[i + 1]) {
    i--;
  }
  if (i >= 0) {
    // Swap it with the rightmost number in the tail that is larger.
    let j = nums.length - 1;
    while (nums[j] <= nums[i]) {
      j--;
    }
    [nums[i], nums[j]] = [nums[j], nums[i]];
  }
  // The tail is decreasing, so reversing it makes it increasing.
  for (let left = i + 1, right = nums.length - 1; left < right; left++, right--) {
    [nums[left], nums[right]] = [nums[right], nums[left]];
  }
}

const [n, ...rest] = input.trim().split(/\s+/).map(Number);
const nums = rest.slice(0, n);
