#include <algorithm>
#include <cstddef>
#include <iostream>
#include <utility>
#include <vector>

void nextPermutation(std::vector<int>& nums) {
    int n = static_cast<int>(nums.size());
    // The pivot is the rightmost number smaller than the number after it.
    int i = n - 2;
    while (i >= 0 && nums[i] >= nums[i + 1]) {
        i--;
    }
    if (i >= 0) {
        // Swap it with the rightmost number in the tail that is larger.
        int j = n - 1;
        while (nums[j] <= nums[i]) {
            j--;
        }
        std::swap(nums[i], nums[j]);
    }
    // The tail is decreasing, so reversing it makes it increasing.
    std::reverse(nums.begin() + i + 1, nums.end());
}

int main() {
    int n;
    std::cin >> n;
    std::vector<int> nums(n);
    for (int i = 0; i < n; i++) {
        std::cin >> nums[i];
    }
    nextPermutation(nums);
    for (std::size_t i = 0; i < nums.size(); i++) {
        if (i > 0) {
            std::cout << " ";
        }
        std::cout << nums[i];
