        if (i >= 0) {
            // Swap it with the rightmost number in the tail that is larger.
            int j = nums.length - 1;
            while (nums[j] <= nums[i]) {
                j--;
            }
            swap(nums, i, j);
        }
        // The tail is decreasing, so reversing it makes it increasing.
        for (int left = i + 1, right = nums.length - 1; left < right; left++, right--) {
            swap(nums, left, right);
