package main

import (
	"fmt"
	"strconv"
	"strings"
)

func nextPermutation(nums []int) {
	// The pivot is the rightmost number smaller than the number after it.
	i := len(nums) - 2
	for i >= 0 && nums[i] >= nums[i+1] {
		i--
	}
	if i >= 0 {
		// Swap it with the rightmost number in the tail that is larger.
		j := len(nums) - 1
		for nums[j] <= nums[i] {
			j--
		}
		nums[i], nums[j] = nums[j], nums[i]
	}
	// The tail is decreasing, so reversing it makes it increasing.
	for left, right := i+1, len(nums)-1; left < right; left, right = left+1, right-1 {
		nums[left], nums[right] = nums[right], nums[left]
	}
}

func main() {
	var n int
	fmt.Scan(&n)
	nums := make([]int, n)
	for i := range nums {
		fmt.Scan(&nums[i])
	}
	nextPermutation(nums)
	parts := make([]string, n)
	for i, num := range nums {
		parts[i] = strconv.Itoa(num)
	}
	fmt.Println(strings.Join(parts, " "))
}

