function nextPermutation(nums: number[]): void {
  const at = (k: number): number => nums[k] ?? 0;
  // The pivot is the rightmost number smaller than the number after it.
  let i = nums.length - 2;
  while (i >= 0 && at(i) >= at(i + 1)) {
    i--;
  }
  if (i >= 0) {
    // Swap it with the rightmost number in the tail that is larger.
    let j = nums.length - 1;
    while (at(j) <= at(i)) {
      j--;
    }
    [nums[i], nums[j]] = [at(j), at(i)];
  }
  // The tail is decreasing, so reversing it makes it increasing.
  for (let left = i + 1, right = nums.length - 1; left < right; left++, right--) {
    [nums[left], nums[right]] = [at(right), at(left)];
  }
}

const [n = 0, ...rest] = input.trim().split(/\s+/).map(Number);
const nums = rest.slice(0, n);
nextPermutation(nums);
console.log(nums.join(" "));
